package robofight.fireline.web

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertIs
import kotlin.test.assertTrue
import robofight.fireline.FirelineRun
import robofight.fireline.Missions

/**
 * W3 permalink gate for the `FLW1-` share-link codec (`Permalink.kt`,
 * docs/FIRELINE-WEB.md §8). Every expected link string and payload below is a
 * pinned constant generated by `docs/web/fixtures/permalink_fixture_gen.py`
 * from the live authored firmware sources (`permalink_sources.tsv`, recorded by
 * `PermalinkSources.kt` from `Missions.ALL`), and each pinned link was already
 * decompressed by Python's independent `gzip` module when it was pinned.
 *
 * What this suite proves on wasmJs:
 *  1. `Permalink.encode` reproduces the Python generator's link string
 *     byte-for-byte (the two gzip framings agree), for every pinned scenario;
 *  2. `Permalink.decode` recovers mission id, seed override, firmware name and
 *     the exact authored source text from those same links;
 *  3. a decoded mission-02 link reproduces the committed engine run (tick 102,
 *     fingerprint `5cd373d7f4a15c81` from `parity_matrix.tsv` row `2-reference`,
 *     engine 4; the plan's G4 text still cites the engine-v1 value `$47e28d84`):
 *     the link really is a reproduction recipe (§8), not a label;
 *  4. hostile or foreign links are refused with reasons, including sources that
 *     would breach the `WebInputLimits` ceilings (§13 "limits enforced before
 *     allocation").
 */
class W3PermalinkTest {

    private val model = ConsoleModel()
    private val authoredIds = WebLibrary.authoredMissionIds(Missions.ALL)

    companion object {
        private const val BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    }

    /** Decode a fixture's base64 (standard alphabet) source field. This is the
     *  fixture envelope, not the codec under test; `Permalink` carries its own
     *  base64url implementation. */
    private fun decode64(text: String): String {
        val out = ArrayList<Int>()
        var acc = 0
        var bits = 0
        for (ch in text) {
            if (ch == '=') break
            val v = BASE64_ALPHABET.indexOf(ch.toString())
            if (v < 0) throw IllegalArgumentException("fixture base64 has an unexpected character")
            acc = (acc shl 6) or v
            bits += 6
            if (bits >= 8) {
                bits -= 8
                out.add((acc shr bits) and 0xFF)
            }
        }
        return out.map { it.toByte() }.toByteArray().decodeToString()
    }

    @Test
    fun pinnedScenarioCountIsTheFixtureCount() {
        assertEquals(PERMALINK_EXPECTED_SCENARIOS, PINNED_PERMALINKS.size)
        assertTrue(PINNED_PERMALINKS.all { it.link.startsWith(Permalink.PREFIX) })
    }

    @Test
    fun kotlinEncoderReproducesEveryPinnedPythonLinkByteForByte() {
        for (p in PINNED_PERMALINKS) {
            val mission = Missions.ALL.first { it.id == p.missionId }
            val encoded = Permalink.encode(mission, p.firmwareName, decode64(p.sourceBase64), p.seedOverride)
            assertEquals(p.link, encoded, "encode mismatch for scenario ${p.scenario}")
        }
    }

    @Test
    fun everyPinnedLinkDecodesBackToItsExactRecipeFields() {
        for (p in PINNED_PERMALINKS) {
            val decoded = Permalink.decode(p.link, authoredIds)
            if (decoded is Permalink.Decoded.Refused) {
                throw AssertionError("decode refused for ${p.scenario}: ${decoded.problems.joinToString(" | ")}")
            }
            assertIs<Permalink.Decoded.Ok>(decoded, "decode refused for ${p.scenario}")
            assertEquals(p.missionId, decoded.missionId, p.scenario)
            assertEquals(p.seedOverride, decoded.seedOverride, p.scenario)
            assertEquals(p.firmwareName, decoded.firmwareName, p.scenario)
            assertEquals(decode64(p.sourceBase64), decoded.firmwareSource, p.scenario)
        }
    }

    @Test
    fun fragmentFormRoundTripsThroughDecode() {
        val mission = Missions.ALL.first { it.id == 2 }
        val fragment = Permalink.fragmentFor(mission, "CORRIDOR-REF.ASM", mission.referenceSource)
        assertTrue(fragment.startsWith("#run="), fragment)
        val decoded = Permalink.decode(fragment, authoredIds)
        assertIs<Permalink.Decoded.Ok>(decoded)
        assertEquals(2, decoded.missionId)
        assertEquals(mission.referenceSource, decoded.firmwareSource)
    }

    @Test
    fun aDecodedMission02LinkReproducesTheCommittedEngineRun() {
        // parity_matrix.tsv row 2-reference (engine v4): SUCCESS at tick 102,
        // final hash 5cd373d7f4a15c81. The plan's §2 / G4 citations still print
        // the engine-v1 value `$47e28d84`; PLAN-EDGE-WALLS.md section 11.1
        // records v1 -> v2 and PLAN-RECONCILE-MAIN-01.md §7 decision 4 records
        // the v2 -> v4 bump (docs/web/fixtures/README.md).
        val decoded = Permalink.decode(pinned("2-reference").link, authoredIds)
        assertIs<Permalink.Decoded.Ok>(decoded)
        val mission = Missions.ALL.first { it.id == decoded.missionId }
        val result = FirelineRun.runWithGuard(mission, mission.descriptorForSource(decoded.firmwareSource))
        assertEquals(102, result.tick)
        assertEquals("5cd373d7f4a15c81", result.finalStateHash)
    }

    @Test
    fun seedOverrideSurvivesTheRoundTrip() {
        val decoded = Permalink.decode(pinned("2-reference-seed7").link, authoredIds)
        assertIs<Permalink.Decoded.Ok>(decoded)
        assertEquals(7, decoded.seedOverride)
        assertEquals("CUSTOM-SEED.ASM", decoded.firmwareName)
    }

    @Test
    fun foreignAndCorruptedLinksAreRefusedWithReasons() {
        val p = pinned("2-reference")
        val cases = listOf(
            "foreign prefix" to Permalink.decode("FLW2-abcd", authoredIds),
            "bad base64url" to Permalink.decode("#run=not-base64!!", authoredIds),
            "truncated stream" to Permalink.decode(p.link.dropLast(4), authoredIds),
            "broken trailer" to Permalink.decode(tamperTail(p.link), authoredIds),
            "corrupted CRC" to Permalink.decode(tamperCrcRegion(p.link), authoredIds),
            "unknown mission id" to Permalink.decode(p.link, setOf(99)),
        )
        for ((label, outcome) in cases) {
            if (outcome is Permalink.Decoded.Ok) {
                val body = pinned("2-reference").link.substring(Permalink.PREFIX.length)
                throw AssertionError(
                    "expected refusal: $label; link chars ${body.length - 14}..${body.length} " +
                        body.substring(body.length - 14) + ", decoded mission " + outcome.missionId,
                )
            }
            assertIs<Permalink.Decoded.Refused>(outcome, "expected refusal: $label")
            assertTrue(outcome.problems.isNotEmpty(), label)
        }
    }

    @Test
    fun oversizedSourceIsRefusedBeforeAnyAllocation() {
        // Gate G6 order: WebInputLimits ceilings run before assembly and before
        // any world allocation, on both the draft path and the link decoder.
        val oversized = buildString { repeat(1201) { append("loop: WAIT\n") } }
        val draft = model.draftFirmware(2, "OVERSIZED.ASM", oversized)
        assertIs<ConsoleModel.DraftResult.Rejected>(draft)
        assertTrue(draft.problems.any { it.contains("limit is 1200") }, draft.problems.toString())
        assertTrue(WebLibrary.sourceProblems(oversized).any { it.contains("bytes") })
    }

    /** Flip the second-to-last encoded character. The trailing character of a
     *  link whose length % 4 == 2 only carries padding bits the decoder drops,
     *  so a mutation there is deliberately invisible; this one lands inside the
     *  gzip trailer's ISIZE bytes. */
    private fun tamperTail(link: String): String {
        val body = link.substring(Permalink.PREFIX.length)
        val index = body.length - 2
        val chars = body.toCharArray()
        chars[index] = if (chars[index] == 'A') 'B' else 'A'
        return Permalink.PREFIX + chars.concatToString()
    }

    /** Flip a character in the window that decodes to the CRC32 field (the 4
     *  bytes before ISIZE), so the decoder must actually compare the CRC rather
     *  than only the length. */
    private fun tamperCrcRegion(link: String): String {
        val body = link.substring(Permalink.PREFIX.length)
        val index = (body.length - 11).coerceAtLeast(0)
        val chars = body.toCharArray()
        val current = chars[index]
        chars[index] = if (current == 'A') 'B' else 'A'
        return Permalink.PREFIX + chars.concatToString()
    }

    private fun pinned(scenario: String): PinnedPermalink =
        PINNED_PERMALINKS.firstOrNull { it.scenario == scenario }
            ?: throw IllegalArgumentException("fixture has no scenario $scenario")
}
